def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    base=grid[-1]; runs=[]; c=0
    while c<w:
        if base[c]==0: c+=1; continue
        run=[]
        while c<w and base[c]!=0:
            run.append(base[c]); c+=1
        runs.append(run)
    lookup={v:(run,i) for run in runs for i,v in enumerate(run)}
    for r in range(h-1):
        for c in range(w):
            v=grid[r][c]
            if not v or v not in lookup: continue
            # Only isolated markers are transformed, not adjacent header/object runs.
            if any(0<=rr<h and 0<=cc<w and grid[rr][cc] for rr in range(r-1,r+2) for cc in range(c-1,c+2) if (rr,cc)!=(r,c)):
                continue
            run,i=lookup[v]; start=c-i
            for j,x in enumerate(run):
                q=start+j
                if 0<=q<w: out[r][q]=x
    return out
